      showToast("⚠️ Copy failed — select text manually.", "error");
    };
    var fallbackPlain = function () {
      try {
        var ta = document.createElement("textarea");
        ta.value = clipText;
        ta.style.position = "fixed";
        ta.style.opacity = "0";
        document.body.appendChild(ta);
        ta.select();
        document.execCommand("copy");
        document.body.removeChild(ta);
        done();
      } catch (e) {
        fail();
      }
    };
    if (navigator.clipboard && window.ClipboardItem && navigator.clipboard.write) {
      try {
        var item = new ClipboardItem({
          "text/html": new Blob([clipHtml], { type: "text/html" }),
          "text/plain": new Blob([clipText], { type: "text/plain" }),
        });
        navigator.clipboard
          .write([item])
          .then(done)
          .catch(function () {
            if (navigator.clipboard.writeText) {
              navigator.clipboard.writeText(clipText).then(done).catch(fallbackPlain);
            } else {
              fallbackPlain();
            }
          });
      } catch (e) {
        if (navigator.clipboard.writeText) {
          navigator.clipboard.writeText(clipText).then(done).catch(fallbackPlain);
        } else {
          fallbackPlain();
        }
      }
    } else if (navigator.clipboard && navigator.clipboard.writeText) {
      navigator.clipboard.writeText(clipText).then(done).catch(fallbackPlain);
    } else {
      fallbackPlain();
    }
  };
