functions.ebLocate:
function ebLocate(idx, btn) {
  if (!window._ebData || !window._ebData.commitments[idx]) return;
  var item = window._ebData.commitments[idx];
  var target = (item.quote || "").trim();
  if (!target && item.ref && item.ref !== "—" && item.ref !== "Manual") target = String(item.ref).trim();
  if (!target && item.details) {
    var firstSentence = String(item.details).split(/(?<=[.!?])\s+/)[0];
    if (firstSentence && firstSentence.length > 8) target = firstSentence.substring(0, 200);
  }
  if (!target) {
    showToast("⚠️ No anchor text — regenerate the brief or add a quote.");
    return;
  }
  if (typeof locateText === "function") {
    locateText(target, btn, true);
  } else {
    showToast("⚠️ Locate helper unavailable.");
  }
}

