    "</div>" +
    '<div style="font-size:12px; color:#475569; margin-bottom:10px; text-align:left;">Edit the key terms ELI summarizes for each agreement type. One term per line.</div>' +
    '<select id="ebsType" style="width:100%; padding:8px; font-size:12px; border:1px solid #cbd5e1; border-radius:4px; margin-bottom:8px; box-sizing:border-box;">' +
    optHtml +
    "</select>" +
    '<textarea id="ebsTerms" style="width:100%; min-height:220px; flex:1; padding:8px; font-size:12px; border:1px solid #cbd5e1; border-radius:4px; font-family:\'Inter\', system-ui, sans-serif; box-sizing:border-box; resize:vertical;"></textarea>' +
    '<div style="margin-top:8px; margin-bottom:8px; padding:10px; background:#f8fafc; border:1px solid #e2e8f0; border-radius:4px; display:flex; align-items:center; gap:8px;">' +
    '<input type="checkbox" id="ebsCompareTemplate" style="transform:scale(1.15); cursor:pointer;">' +
    '<label for="ebsCompareTemplate" style="font-size:12px; font-weight:700; color:#1e293b; cursor:pointer;">Flag Major Deviations from Standard Template (if available)</label>' +
    "</div>" +
    '<div style="font-size:10px; color:#94a3b8; margin-top:2px; text-align:left;">Leave the textarea blank and click Save to fall back to defaults.</div>' +
    '<div class="eli-dialog-actions" style="margin-top:12px; flex-shrink:0;">' +
    '<button type="button" data-ebs-reset class="btn-action" style="flex:1;">↩️ Reset This Type</button>' +
    '<button type="button" data-ebs-save class="btn-action" style="flex:1; font-weight:bold;">💾 Save</button>' +
    '<button type="button" data-ebs-cancel class="btn-action" style="flex:1;">Cancel</button>' +
    "</div>";
  overlay.appendChild(dialog);
  document.body.appendChild(overlay);
  var sel = dialog.querySelector("#ebsType");
  var area = dialog.querySelector("#ebsTerms");
  var cb = dialog.querySelector("#ebsCompareTemplate");
  function loadType() {
    var terms = getExecBriefTerms(sel.value);
    var devIdx = terms.indexOf("Major Deviations from Standard Agreement");
    if (devIdx > -1) {
      cb.checked = true;
      terms.splice(devIdx, 1);
    } else {
      cb.checked = false;
    }
    area.value = terms.join("\n");
  }
  sel.onchange = loadType;
  loadType();
  function closeDialog() {
    overlay.remove();
  }
  dialog.querySelector("[data-ebs-close]").onclick = closeDialog;
  dialog.querySelector("[data-ebs-cancel]").onclick = closeDialog;
  dialog.querySelector("[data-ebs-reset]").onclick = function () {
    clearExecBriefTerms(sel.value);
    loadType();
    showToast("↩️ Cleared " + sel.value + " — re-import master JSON to restore shipped defaults");
  };
  dialog.querySelector("[data-ebs-save]").onclick = function () {
    var terms = area.value
      .split("\n")
      .map(function (s) {
        return s.trim();
      })
      .filter(function (s) {
        return !!s;
      });

    var isDefaultsOnly = terms.length === 0;

    if (cb.checked) {
      if (terms.indexOf("Major Deviations from Standard Agreement") === -1) {
        terms.push("Major Deviations from Standard Agreement");
      }
    }

    if (isDefaultsOnly && !cb.checked) {
      clearExecBriefTerms(sel.value);
      showToast("↩️ " + sel.value + " cleared (will use generic terms)");
    } else {
      setExecBriefTerms(sel.value, terms);
      showToast("✅ Saved key terms for " + sel.value);
    }
    closeDialog();
  };
}
